Lemma act_member_meta : forall A sc x, WF A -> In x (a_active A sc) ->
  exists mt aib sl, a_meta A x = Some mt /\ mt_role mt = RGroup aib sl /\ mt_sc mt = sc /\
    0x1000 <= x /\ x + 40 <= alloc_ceiling /\ (forall j, 0 <= j < 40 -> dom A (x + j)) /\
