  Theorem ts_rotate : forall (K : unit -> M R) P,
    (forall s', II sp0 argv envp cb D A1 s' -> FR A s A1 s' -> ms_vm s' = ms_vm s ->
       tsafe (K tt s') P) ->
    tsafe ((x <- m_sd (Z_to_bv 64 (caddr (KActive sc))) (Z_to_bv 64 (mt_next mth)) ;; K x) s) P.
