Definition links_only (A A' : astate) : Prop :=
  forall x mt, a_meta A x = Some mt ->
    exists mt', a_meta A' x = Some mt' /\ mt_role mt' = mt_role mt /\
      forall fl, fl <> FPrev -> fl <> FNext -> mt_f mt' fl = mt_f mt fl.

